function mcpRecordFor(input) {
  if (input.transport === "http" || input.transport === "sse") {
    return {
      id: input.id,
      label: input.label,
      command: "",
      args: [],
      enabled: input.enabled ?? true,
      requestTimeoutMs: input.requestTimeoutMs ?? 15_000,
      envNameCount: 0,
      hasPrivateEnv: false,
      transport: input.transport,
      url: input.url,
      headerCount: Object.keys(input.headers ?? {}).length,
      hasPrivateHeaders: Object.keys(input.headers ?? {}).length > 0,
    };
  }
  return {
    id: input.id,
    label: input.label,
    command: input.command,
    args: [...input.args],
    enabled: input.enabled ?? true,
    requestTimeoutMs: input.requestTimeoutMs ?? 15_000,
    envNameCount: 0,
    hasPrivateEnv: false,
    transport: "stdio",
    headerCount: 0,
    hasPrivateHeaders: false,
  };
}

function createFakeService(workspace, { createDiffPatch, ForgeError }) {
  const fixtureError = (code, message) => new ForgeError(code, message);
  const sessions = new Map();
  const workbenchSessions = new Set();
  const checkpointStates = new Map();
  const sources = new Map(
    INITIAL_SOURCES.map((source) => [source.id, clone(source)]),
  );
  const sourceModels = new Map([
    ["fixture-local", [MODEL]],
    ["fixture-cloud", ["fixture-cloud-model", "fixture-cloud-mini"]],
  ]);
  const routes = new Map(
    INITIAL_ROUTE_GROUPS.map((group) => [group.id, clone(group)]),
  );
  const mcpRecords = new Map(
    INITIAL_MCP_RECORDS.map((record) => [record.id, clone(record)]),
  );
  let settings = initialSettings();
  let disposed = false;

  const requireSession = (id) => {
    const session = sessions.get(id);
    if (!session) throw fixtureError("not_found", "Unknown native fixture session.");
    return session;
  };

  const summaryOf = (session) => ({
    version: session.version,
    id: session.id,
    title: session.title,
    workspace: session.workspace,
    model: session.model,
    createdAt: session.createdAt,
    ...(session.providerSourceId === undefined
      ? {}
      : { providerSourceId: session.providerSourceId }),
    ...(session.routeGroupId === undefined
      ? {}
      : { routeGroupId: session.routeGroupId }),
    updatedAt: session.updatedAt,
    status: session.status,
    ...(session.parentSessionId === undefined
      ? {}
      : { parentSessionId: session.parentSessionId }),
    ...(session.archived === undefined ? {} : { archived: session.archived }),
  });

  const eventFor = (session, type, extra) => ({
    sessionId: session.id,
    timestamp: timestamp(),
    type,
    ...extra,
  });

  const pushEvent = (session, onEvent, event) => {
    onEvent(event);
    session.events.push(event);
    return event;
  };

  const emitGenerationFinished = (
    session,
    onEvent,
    generationId,
    turn,
    status,
  ) => {
    pushEvent(
      session,
      onEvent,
      eventFor(session, "generation_finished", {
        generationId,
        status,
        turn,
      }),
    );
  };

  const finishCompleted = (
    session,
    onEvent,
    {
      generationId,
      turn,
      answer,
      toolCalls,
      generationFinished,
      usage,
    },
  ) => {
    if (!generationFinished) {
      emitGenerationFinished(session, onEvent, generationId, turn, "completed");
    }
    const messageIndex = session.messages.length;
    session.messages.push({
      role: "assistant",
      content: answer,
      generationId,
    });
    session.status = "completed";
    session.updatedAt = timestamp();
    pushEvent(
      session,
      onEvent,
      eventFor(session, "run_finished", {
        status: "completed",
        turn,
        turns: 1,
        toolCalls,
        messageIndex,
        ...(usage === undefined
          ? {}
          : { usage: clone(usage), usageComplete: true }),
      }),
    );
    return clone(session);
  };

  const finishCancelled = (
    session,
    onEvent,
    { generationId, turn, generationFinished, toolCalls = 0 },
  ) => {
    if (!generationFinished) {
      emitGenerationFinished(session, onEvent, generationId, turn, "cancelled");
    }
    session.status = "cancelled";
    session.updatedAt = timestamp();
    pushEvent(
      session,
      onEvent,
      eventFor(session, "run_finished", {
        status: "cancelled",
        turn,
        turns: 1,
        toolCalls,
      }),
    );
    return clone(session);
  };

  const runApproval = async (
    session,
    onEvent,
    approve,
    signal,
    generationId,
    turn,
  ) => {
    pushEvent(
      session,
      onEvent,
      eventFor(session, "text_delta", {
        generationId,
        turn,
        text: "正在请求一次离线工具审批。",
      }),
    );
    emitGenerationFinished(session, onEvent, generationId, turn, "completed");

    const toolCallId = randomUUID();
    const request = {
      id: randomUUID(),
      sessionId: session.id,
      toolCallId,
      toolName: "write_file",
      description:
        "Offline native fixture: approve a simulated write_file call. No real tool runtime or provider is involved.",
      command: ["echo", "offline-native-fixture-approved"],
    };
    session.status = "awaiting_approval";
    session.updatedAt = timestamp();
    pushEvent(
      session,
      onEvent,
      eventFor(session, "approval_requested", { request, turn }),
    );

    const approved = await approve(request, signal);
    if (signal.aborted) {
      return finishCancelled(session, onEvent, {
        generationId,
        turn,
        generationFinished: true,
      });
    }

    const call = {
      id: toolCallId,
      type: "function",
      function: {
        name: "write_file",
        arguments: JSON.stringify({
          path: "fixture-approval.txt",
          content: "offline native fixture approval\n",
        }),
      },
    };
    pushEvent(
      session,
      onEvent,
      eventFor(session, "tool_started", { call, turn }),
    );

    let result;
    if (approved) {
      try {
        await writeFile(
          join(session.workspace, "fixture-approval.txt"),
          "offline native fixture approval\n",
          "utf8",
        );
        result = {
          content:
            "wrote fixture-approval.txt in the isolated fixture workspace",
          isError: false,
        };
      } catch {
        result = {
          content: "could not write the isolated fixture file",
          isError: true,
        };
      }
    } else {
      result = {
        content: "approval denied; no fixture file was written",
        isError: true,
      };
    }
    pushEvent(
      session,
      onEvent,
      eventFor(session, "tool_finished", { toolCallId, result, turn }),
    );

    return finishCompleted(session, onEvent, {
      generationId,
      turn,
      generationFinished: true,
      toolCalls: 1,
      answer: approved
        ? "已完成离线审批：模拟工具在隔离工作区写入了 fixture-approval.txt。"
        : "离线工具审批被拒绝；没有写入 fixture 文件。",
    });
  };

  const runSlow = async (session, onEvent, signal, generationId, turn) => {
    pushEvent(
      session,
      onEvent,
      eventFor(session, "text_delta", {
        generationId,
        turn,
        text: "slow fixture：正在等待 cancelRun（最多 120 秒）。",
      }),
    );
    const aborted = await waitForAbort(signal, SLOW_TIMEOUT_MS);
    if (aborted) {
      return finishCancelled(session, onEvent, {
        generationId,
        turn,
        generationFinished: false,
      });
    }
    return finishCompleted(session, onEvent, {
      generationId,
      turn,
      generationFinished: false,
      toolCalls: 0,
      answer: "slow fixture window elapsed without cancelRun.",
    });
  };

  const runWorkbench = async (session, onEvent, signal, generationId, turn) => {
    const plan = clone(WORKBENCH_PLAN);
    const answer = workbenchAnswer();

    pushEvent(
      session,
      onEvent,
      eventFor(session, "reasoning_delta", {
        generationId,
        turn,
        text: "离线 fixture：准备结构化工作台数据，不调用模型。",
      }),
    );
    for (const chunk of splitText(answer)) {
      if (await sleepUnlessAborted(signal, DELTA_DELAY_MS)) {
        return finishCancelled(session, onEvent, {
          generationId,
          turn,
          generationFinished: false,
        });
      }
      pushEvent(
        session,
        onEvent,
        eventFor(session, "text_delta", {
          generationId,
          turn,
          text: chunk,
        }),
      );
    }
    if (signal.aborted) {
      return finishCancelled(session, onEvent, {
        generationId,
        turn,
        generationFinished: false,
      });
    }

    const reportPath = join(session.workspace, WORKBENCH_REPORT_PATH);
    let before = "";
    try {
      before = await readFile(reportPath, "utf8");
    } catch {
      before = "";
    }
    const after = workbenchReport();
    await mkdir(dirname(reportPath), { recursive: true });
    await writeFile(reportPath, after, "utf8");
    const change = {
      path: WORKBENCH_REPORT_PATH,
      kind: before === "" ? "created" : "modified",
      patch: createDiffPatch(before, after),
    };
    session.changes = [
      ...session.changes.filter((item) => item.path !== change.path),
      change,
    ];
    session.plan = plan;
    session.plans = [plan];
    session.contextSummary = {
      content:
        "Offline fixture context summary: this session only used isolated fixture files and simulated usage.",
      boundary: session.messages.length,
      fallback: false,
    };
    workbenchSessions.add(session.id);
    session.updatedAt = timestamp();

    pushEvent(
      session,
      onEvent,
      eventFor(session, "context_usage", {
        usage: {
          windowTokens: 32_768,
          budgetTokens: 24_576,
          usedTokens: 8_421,
          estimated: true,
          basis: "projected",
          parts: {
            instructions: 512,
            memory: 1_024,
            conversation: 4_096,
            tools: 2_789,
          },
        },
      }),
    );
    pushEvent(
      session,
      onEvent,
      eventFor(session, "plan_updated", { plan }),
    );

    const toolCallId = randomUUID();
    const call = {
      id: toolCallId,
      type: "function",
      function: {
        name: "fixture_workbench_report",
        arguments: JSON.stringify({ path: change.path }),
      },
    };
    pushEvent(
      session,
      onEvent,
      eventFor(session, "tool_started", {
        call,
        callIndex: 0,
        generationId,
        turn,
      }),
    );
    pushEvent(
      session,
      onEvent,
      eventFor(session, "tool_finished", {
        callIndex: 0,
        generationId,
        toolCallId,
        result: {
          content: `wrote ${change.path} in the isolated fixture workspace`,
          isError: false,
          changes: [change],
        },
        turn,
      }),
    );

    return finishCompleted(session, onEvent, {
      generationId,
      turn,
      generationFinished: false,
      toolCalls: 1,
      answer,
      usage: WORKBENCH_USAGE,
    });
  };

  const projectSource = (source) => {
    settings.baseUrl = source.baseUrl;
    settings.model = source.model;
    if (source.apiMode === undefined) delete settings.apiMode;
    else settings.apiMode = source.apiMode;
  };

  const syncSettings = () => {
    settings.providerSources = [...sources.values()].map((source) =>
      clone(source),
    );
    settings.routeGroups = [...routes.values()].map((group) => clone(group));
    if (
      settings.activeSourceId !== undefined &&
      !sources.has(settings.activeSourceId)
    ) {
      settings.activeSourceId = sources.keys().next().value;
    }
    if (settings.activeSourceId === undefined) {
      delete settings.activeSourceId;
    }
    settings.hasApiKey = false;
    settings.isConfigured =
      settings.baseUrl !== "" && settings.model !== "";
  };

  const applySourceOperation = (operation) => {
    if (operation.type === "save") {
      const existing = sources.get(operation.source.id);
      const expected = operation.expectedRevision;
      if (
        expected !== undefined &&
        (existing?.revision ?? 0) !== expected
      ) {
        throw fixtureError(
          "invalid_input",
          "该来源已被其他窗口或 CLI 修改。请重新加载设置后再保存，避免覆盖对方的改动。",
        );
      }
      const revision = (existing?.revision ?? 0) + 1;
      const source = operation.source;
      const saved = {
        id: source.id,
        label: source.label,
        baseUrl: source.baseUrl,
        model: source.model,
        revision,
        hasApiKey: false,
        ...(source.apiMode === undefined ? {} : { apiMode: source.apiMode }),
        ...(source.preset === undefined ? {} : { preset: source.preset }),
        ...(source.endpoints === undefined
          ? {}
          : { endpoints: clone(source.endpoints) }),
        ...(source.modelSelection === undefined
          ? {}
          : { modelSelection: clone(source.modelSelection) }),
        ...(source.modelAliases === undefined
          ? {}
          : { modelAliases: clone(source.modelAliases) }),
        ...(source.credentialRouting === undefined
          ? {}
          : { credentialRouting: source.credentialRouting }),
        ...(source.sticky === undefined ? {} : { sticky: source.sticky }),
      };
      sources.set(saved.id, saved);
      const selected =
        source.modelSelection?.mode === "selected"
          ? source.modelSelection.models ?? []
          : [];
      const models = [...new Set([...selected, source.model].filter(Boolean))];
      sourceModels.set(saved.id, models.length ? models : [MODEL]);
      // The real store keeps the first source active until an explicit switch.
      if (settings.activeSourceId === undefined) {
        settings.activeSourceId = saved.id;
        projectSource(saved);
      } else if (settings.activeSourceId === saved.id) {
        projectSource(saved);
      }
      return;
    }
    if (operation.type === "activate") {
      const source = sources.get(operation.id);
      if (!source) throw fixtureError("not_found", "Unknown fixture model source.");
      settings.activeSourceId = source.id;
      projectSource(source);
      return;
    }
    if (operation.type === "remove") {
      const source = sources.get(operation.id);
      if (!source) throw fixtureError("not_found", "Unknown fixture model source.");
      const acknowledged = new Set(operation.forgottenSessionIds ?? []);
      const pinned = [...sessions.values()]
        .filter(
          (session) =>
            session.providerSourceId === operation.id &&
            !acknowledged.has(session.id),
        )
        .map((session) => session.id);
      if (pinned.length > 0) {
        throw fixtureError(
          "invalid_input",
          `仍有 ${pinned.length} 个会话绑定此来源（${pinned
            .slice(0, 5)
            .join(", ")}）。确认删除后这些会话将没有来源。`,
        );
      }
      sources.delete(operation.id);
      sourceModels.delete(operation.id);
      if (settings.activeSourceId === operation.id) {
        settings.activeSourceId = sources.keys().next().value;
        const next = sources.get(settings.activeSourceId);
        if (next) projectSource(next);
        else {
          settings.baseUrl = "";
          settings.model = "";
          delete settings.apiMode;
        }
      }
    }
  };

  const applyRouteOperation = (operation) => {
    if (operation.type === "save") {
      routes.set(operation.group.id, clone(operation.group));
      return;
    }
    if (!routes.has(operation.id)) {
      throw fixtureError("not_found", "Unknown fixture route group.");
    }
    routes.delete(operation.id);
  };

  return {
    // The controller attaches the real Core queue consumer to this property.
    // It is assigned by main() before createRuntimeHub(service).
    inputQueue: undefined,

    async getSettings() {
      return clone(settings);
    },

    async updateSettings(input) {
      const request = input ?? {};
      if (request.source) applySourceOperation(request.source);
      for (const operation of request.sources ?? []) {
        applySourceOperation(operation);
      }
      if (request.route) applyRouteOperation(request.route);
      if (request.settings) {
        settings = { ...settings, ...request.settings };
      }
      // apiKey is deliberately ignored: this fixture never stores or echoes a
      // provider credential, and hasApiKey stays false.
      syncSettings();
      return clone(settings);
    },

    async listModels(_signal, sourceId) {
      const id =
        sourceId ?? settings.activeSourceId ?? sources.keys().next().value;
      const source = sources.get(id);
      if (!source) throw fixtureError("not_found", "Unknown fixture model source.");
      return clone(sourceModels.get(id) ?? [source.model || MODEL]);
    },

    async listSessions() {
      return [...sessions.values()]
        .sort(
          (left, right) =>
            right.updatedAt.localeCompare(left.updatedAt) ||
            left.id.localeCompare(right.id),
        )
        .map(summaryOf);
    },

    async createSession(input) {
      const requestedWorkspace = resolve(input.workspace);
      if (requestedWorkspace !== workspace) {
        throw fixtureError(
          "invalid_input",
          "The native fixture only accepts its isolated workspace.",
        );
      }
      const now = timestamp();
      const active = settings.activeSourceId
        ? sources.get(settings.activeSourceId)
        : undefined;
      const session = {
        version: 1,
        id: randomUUID(),
        title: input.title ?? `Native fixture ${sessions.size + 1}`,
        workspace: workspace,
        model:
          input.model || active?.model || settings.model || MODEL,
        ...(input.providerSourceId === undefined
          ? settings.activeSourceId === undefined
            ? {}
            : { providerSourceId: settings.activeSourceId }
          : { providerSourceId: input.providerSourceId }),
        ...(input.routeGroupId === undefined
          ? {}
          : { routeGroupId: input.routeGroupId }),
        createdAt: now,
        updatedAt: now,
        status: "idle",
        messages: [],
        events: [],
        changes: [],
        plans: [],
        titleSource: input.title ? "user" : "default",
      };
      sessions.set(session.id, session);
      return clone(session);
    },

    async getSession(id) {
      return clone(requireSession(id));
    },

    async renameSession(id, title) {
      const session = requireSession(id);
      session.title = title;
      session.titleSource = "user";
      session.updatedAt = timestamp();
      return clone(session);
    },

    async archiveSession(id, archived) {
      const session = requireSession(id);
      session.archived = archived;
      session.updatedAt = timestamp();
      return clone(session);
    },

    async forkSession(id, boundary) {
      const source = requireSession(id);
      const end = boundary ?? source.messages.length;
      if (!Number.isInteger(end) || end < 0 || end > source.messages.length) {
        throw fixtureError("invalid_input", "Invalid fork boundary.");
      }
      const now = timestamp();
      const title = `Fork: ${source.title}`.slice(0, 256);
      const fork = {
        version: 1,
        id: randomUUID(),
        title,
        workspace: source.workspace,
        model: source.model,
        ...(source.providerSourceId === undefined
          ? {}
          : { providerSourceId: source.providerSourceId }),
        ...(source.routeGroupId === undefined
          ? {}
          : { routeGroupId: source.routeGroupId }),
        createdAt: now,
        updatedAt: now,
        status: "idle",
        messages: clone(source.messages.slice(0, end)),
        events: [],
        changes: [],
        plans: clone(source.plans ?? []),
        titleSource: "default",
        ...(source.plan === undefined ? {} : { plan: clone(source.plan) }),
        ...(source.contextSummary !== undefined &&
        source.contextSummary.boundary <= end
          ? { contextSummary: clone(source.contextSummary) }
          : {}),
        ...(source.permissionCeiling === undefined
          ? {}
          : { permissionCeiling: source.permissionCeiling }),
        ...(source.parentSessionId === undefined
          ? {}
          : { parentSessionId: source.parentSessionId }),
        ...(source.agentTask === undefined
          ? {}
          : { agentTask: source.agentTask }),
        ...(source.ownership === undefined
          ? {}
          : { ownership: source.ownership }),
        ...(source.writePaths === undefined
          ? {}
          : { writePaths: clone(source.writePaths) }),
        forkedFrom: id,
      };
      sessions.set(fork.id, fork);
      if (workbenchSessions.has(id)) workbenchSessions.add(fork.id);
      return clone(fork);
    },

    async compactSession(id) {
      return clone(requireSession(id));
    },

    async cancelSession() {
      // Active runs are stopped through the public `cancelRun` RPC.
      return false;
    },

    async getProjectContext(id) {
      const session = requireSession(id);
      return {
        workspace: session.workspace,
        instructionSources: [
          {
            path: "AGENTS.md",
            order: 0,
            bytes: Buffer.byteLength(FIXTURE_FILES["AGENTS.md"], "utf8"),
          },
          {
            path: "docs/AGENTS.md",
            order: 1,
            bytes: Buffer.byteLength(FIXTURE_FILES["docs/AGENTS.md"], "utf8"),
          },
        ],
        skills: [
          {
            id: "fixture-workbench",
            name: "Fixture Workbench",
            description:
              "Simulated offline skill metadata for the native workbench UI. It is never executed.",
            version: "1.0.0",
            sourceDirectory: join(
              session.workspace,
              ".forge",
              "skills",
              "fixture-workbench",
            ),
            provenance: "workspace-forge",
          },
        ],
        warnings: [
          "Native fixture project context is simulated from isolated fixture files; it does not read user-level Forge instructions or skills.",
        ],
        counts: { instructions: 2, skills: 1, warnings: 1 },
      };
    },

    async getDiagnostics(id) {
      const session = requireSession(id);
      const transcriptChars = JSON.stringify(session.messages).length;
      const projectedChars = JSON.stringify({
        messages: session.messages,
        plan: session.plan ?? null,
        plans: session.plans ?? [],
        changes: session.changes,
      }).length;
      return {
        transcriptChars,
        projectedChars,
        messageCount: session.messages.length,
        summaryFallback: false,
      };
    },

    async getUsageStats() {
      const actual = {
        promptTokens: 0,
        completionTokens: 0,
        cachedTokens: 0,
        runs: 0,
      };
      for (const session of sessions.values()) {
        for (const event of session.events) {
          if (event.type === "run_started") actual.runs += 1;
          if (event.type === "run_finished" && event.usage) {
            actual.promptTokens += event.usage.promptTokens;
            actual.completionTokens += event.usage.completionTokens;
            actual.cachedTokens += event.usage.cachedPromptTokens ?? 0;
          }
        }
      }
      const totalPromptTokens =
        SIMULATED_USAGE.promptTokens + actual.promptTokens;
      const totalCompletionTokens =
        SIMULATED_USAGE.completionTokens + actual.completionTokens;
      const totalCachedTokens =
        SIMULATED_USAGE.cachedTokens + actual.cachedTokens;
      const totalTokens = totalPromptTokens + totalCompletionTokens;
      const totalRuns = SIMULATED_USAGE.runs + actual.runs;
      const today = new Date().toISOString().slice(0, 10);
      return {
        totalPromptTokens,
        totalCompletionTokens,
        totalCachedTokens,
        totalTokens,
        totalSessions: sessions.size,
        totalRuns,
        averageCacheRate:
          totalPromptTokens === 0
            ? 0
            : Math.min(1, totalCachedTokens / totalPromptTokens),
        models: [
          {
            model: MODEL,
            promptTokens: totalPromptTokens,
            completionTokens: totalCompletionTokens,
            cachedTokens: totalCachedTokens,
            totalTokens,
            runCount: totalRuns,
            sessionCount: sessions.size,
            requestCount: totalRuns,
          },
        ],
        daily: [
          {
            date: today,
            promptTokens: totalPromptTokens,
            completionTokens: totalCompletionTokens,
            cachedTokens: totalCachedTokens,
            totalTokens,
            runCount: totalRuns,
          },
        ],
        topSessions: [...sessions.values()]
          .sort((left, right) => right.updatedAt.localeCompare(left.updatedAt))
          .map((session) => {
            let promptTokens = 0;
            let completionTokens = 0;
            let cachedTokens = 0;
            let runCount = 0;
            for (const event of session.events) {
              if (event.type === "run_started") runCount += 1;
              if (event.type === "run_finished" && event.usage) {
                promptTokens += event.usage.promptTokens;
                completionTokens += event.usage.completionTokens;
                cachedTokens += event.usage.cachedPromptTokens ?? 0;
              }
            }
            return {
              sessionId: session.id,
              title: session.title,
              workspace: session.workspace,
              model: session.model,
              updatedAt: session.updatedAt,
              promptTokens,
              completionTokens,
              cachedTokens,
              totalTokens: promptTokens + completionTokens,
              runCount,
            };
          }),
        routes: [
          {
            sourceId: settings.activeSourceId ?? "fixture-local",
            model: settings.model || MODEL,
            apiMode: settings.apiMode ?? "chat-completions",
            attempts: totalRuns,
            succeeded: totalRuns,
            failed: 0,
            unknownUsage: 0,
            promptTokens: totalPromptTokens,
            completionTokens: totalCompletionTokens,
            cachedTokens: totalCachedTokens,
            totalTokens,
          },
        ],
        pricing: { state: "unavailable" },
      };
    },

    async listMcpServers() {
      return [...mcpRecords.values()].map((record) => clone(record));
    },

    async registerMcpServer(input) {
      if (mcpRecords.has(input.id)) {
        throw fixtureError("invalid_input", "MCP server id already exists.");
      }
      const record = mcpRecordFor(input);
      mcpRecords.set(record.id, record);
      return clone(record);
    },

    async setMcpEnabled(serverId, enabled) {
      const record = mcpRecords.get(serverId);
      if (!record) throw fixtureError("not_found", "MCP server was not found.");
      mcpRecords.set(serverId, { ...record, enabled });
    },

    async removeMcpServer(serverId) {
      if (!mcpRecords.has(serverId)) {
        throw fixtureError("not_found", "MCP server was not found.");
      }
      mcpRecords.delete(serverId);
    },

    async getMcpHealth(serverId) {
      const record = mcpRecords.get(serverId);
      if (!record) throw fixtureError("not_found", "MCP server was not found.");
      return {
        id: record.id,
        enabled: record.enabled,
        connected: false,
        negotiatedProtocolVersion: null,
        lastError:
          "Offline native fixture: MCP servers are metadata-only; no process or network connection is started.",
        ...(record.transport === undefined
          ? {}
          : { transport: record.transport }),
      };
    },

    async listCheckpoints(id) {
      const session = requireSession(id);
      if (!workbenchSessions.has(id)) return [];
      const state = checkpointStates.get(id);
      return [
        {
          id: SAMPLE_CHECKPOINT_ID,
          sessionId: session.id,
          toolCallId: "fixture-checkpoint-tool-call",
          path: SAMPLE_CHECKPOINT_PATH,
          kind: "modified",
          state: state?.state ?? "completed",
          beforeHash: sha256(EXAMPLE_BEFORE),
          beforeMode: 0o644,
          afterHash: sha256(EXAMPLE_AFTER),
          afterMode: 0o644,
          createdAt: session.createdAt,
          completedAt: session.createdAt,
          ...(state?.restoredAt === undefined
            ? {}
            : { restoredAt: state.restoredAt }),
        },
      ];
    },

    async getCheckpointDiff(id, checkpointId) {
      const session = requireSession(id);
      if (!workbenchSessions.has(id) || checkpointId !== SAMPLE_CHECKPOINT_ID) {
        throw fixtureError("not_found", "Checkpoint was not found.");
      }
      return `--- a/${SAMPLE_CHECKPOINT_PATH}
+++ b/${SAMPLE_CHECKPOINT_PATH}
@@ -1,5 +1,6 @@
 package fixture
${" "}
 object Example {
     const val greeting: String = "hello from offline fixture"
+    const val workbench: Boolean = true
 }
`;
    },

    async restoreCheckpoint(id, checkpointId) {
      const session = requireSession(id);
      if (!workbenchSessions.has(id) || checkpointId !== SAMPLE_CHECKPOINT_ID) {
        throw fixtureError("not_found", "Checkpoint was not found.");
      }
      const target = join(session.workspace, SAMPLE_CHECKPOINT_PATH);
      await mkdir(dirname(target), { recursive: true });
      await writeFile(target, EXAMPLE_AFTER, "utf8");
      checkpointStates.set(id, {
        state: "restored",
        restoredAt: timestamp(),
      });
      session.updatedAt = timestamp();
      return clone(session);
    },

    async run(input, onEvent, approve, signal) {
      if (disposed) throw new Error("The native fixture service is closed.");
      const session = requireSession(input.sessionId);
      const rawPrompt = input.prompt ?? "";
      const prompt = rawPrompt.trim();
      const images = input.images ?? [];
      const turn =
        session.events.filter((event) => event.type === "run_started").length +
        1;
      const userIndex = session.messages.length;
      session.messages.push({
        role: "user",
        content: rawPrompt,
        ...(images.length ? { images } : {}),
      });
      const permission = input.permission ?? settings.defaultPermission;
      const model = input.model || session.model || settings.model;
      const generationId = randomUUID();

      session.model = model;
      session.status = "running";
      session.updatedAt = timestamp();
      pushEvent(
        session,
        onEvent,
        eventFor(session, "run_started", {
          turn,
          messageIndex: userIndex,
          model,
          permission,
        }),
      );
      pushEvent(
        session,
        onEvent,
        eventFor(session, "generation_started", {
          generationId,
          // Core runtime anchors the assistant at the next durable message index.
          messageIndex: session.messages.length,
          turn,
        }),
      );

      try {
        if (prompt.toLowerCase() === "approval") {
          return await runApproval(
            session,
            onEvent,
            approve,
            signal,
            generationId,
            turn,
          );
        }
        if (prompt.toLowerCase() === "slow") {
          return await runSlow(session, onEvent, signal, generationId, turn);
        }
        if (prompt.toLowerCase() === "workbench") {
          return await runWorkbench(
            session,
            onEvent,
            signal,
            generationId,
            turn,
          );
        }

        const answer = answerFor(prompt, images.length);
        for (const chunk of splitText(answer)) {
          if (await sleepUnlessAborted(signal, DELTA_DELAY_MS)) {
            return finishCancelled(session, onEvent, {
              generationId,
              turn,
              generationFinished: false,
            });
          }
          pushEvent(
            session,
            onEvent,
            eventFor(session, "text_delta", {
              generationId,
              turn,
              text: chunk,
            }),
          );
        }
        if (signal.aborted) {
          return finishCancelled(session, onEvent, {
            generationId,
            turn,
            generationFinished: false,
          });
        }
        return finishCompleted(session, onEvent, {
          generationId,
          turn,
          generationFinished: false,
          toolCalls: 0,
          answer,
        });
      } catch (error) {
        session.status = "failed";
        session.updatedAt = timestamp();
        throw error;
      }
    },

    async dispose() {
      disposed = true;
    },
  };
}

async function writeFixtureWorkspace(workspace) {
  for (const [relativePath, content] of Object.entries(FIXTURE_FILES)) {
    const target = join(workspace, relativePath);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, content, "utf8");
  }
}

async function main() {
  if (process.argv.includes("--help") || process.argv.includes("-h")) {
    usage();
    return;
  }

  const port = portFromArguments();
  const required = [
    CORE_SERVER,
    CORE_RUNTIME,
    CORE_INPUT_QUEUE,
    CORE_DIFF,
    CORE_ERRORS,
  ];
  const missing = required.filter((path) => !existsSync(path));
  if (missing.length > 0) {
    console.error(
      `[native-core-fixture] Forge Core build is missing: ${missing.join(", ")}`,
    );
    console.error("Build it first (this fixture does not modify Core):");
    console.error("  (cd ../repos/forge-core && pnpm build)");
    process.exitCode = 1;
    return;
  }

  const runRoot = join(
    ANDROID_ROOT,
    ".gradle",
    "native-fixture",
    `run-${process.pid}-${randomUUID().slice(0, 8)}`,
  );
  const workspace = join(runRoot, "workspace");
  const stateDirectory = join(runRoot, "state");
  await mkdir(workspace, { recursive: true });
  await mkdir(stateDirectory, { recursive: true });
  await writeFixtureWorkspace(workspace);
  // Do not let any incidental Core state discovery touch the real user home.
  process.env.FORGE_HOME = stateDirectory;

  const { createWebHost } = await import(pathToFileURL(CORE_SERVER).href);
  const { createRuntimeHub } = await import(pathToFileURL(CORE_RUNTIME).href);
  const { createDiffPatch } = await import(
    pathToFileURL(CORE_DIFF).href
  );
  const { ForgeError } = await import(pathToFileURL(CORE_ERRORS).href);
  const { inputPredecessor, openInputQueue } = await import(
    pathToFileURL(CORE_INPUT_QUEUE).href
  );

  const service = createFakeService(workspace, { createDiffPatch, ForgeError });
  const inputQueue = await openInputQueue({
    directory: stateDirectory,
    validateSession: async (id) => {
      try {
        await service.getSession(id);
      } catch {
        throw new ForgeError("not_found", "Unknown native fixture session.");
      }
    },
    predecessor: async (id) => {
      try {
        return inputPredecessor(await service.getSession(id));
      } catch {
        throw new ForgeError("not_found", "Unknown native fixture session.");
      }
    },
    prepare: async (input) => {
      const session = await service.getSession(input.sessionId);
      const currentSettings = await service.getSettings();
      return {
        input: {
          ...input,
          model: input.model ?? session.model ?? currentSettings.model,
          permission:
            input.permission ?? currentSettings.defaultPermission,
          mode: input.mode ?? "build",
        },
        providerBinding: FIXTURE_BINDING,
      };
    },
  });
  service.inputQueue = inputQueue;
  const runtime = createRuntimeHub(service);
  let web;
  let shuttingDown = false;

  const cleanup = async () => {
    try {
      await web?.dispose();
    } finally {
      try {
        inputQueue.stop();
        await runtime.dispose();
      } finally {
        await inputQueue.dispose().catch(() => undefined);
        await rm(runRoot, { recursive: true, force: true });
        // Remove only the now-empty parent; other fixture runs are unaffected.
        await rmdir(dirname(runRoot)).catch(() => undefined);
      }
    }
  };

  const shutdown = async (signal) => {
    if (shuttingDown) return;
    shuttingDown = true;
    console.log(`[native-core-fixture] stopping (${signal})`);
    try {
      await cleanup();
    } catch (error) {
      console.error(
        `[native-core-fixture] cleanup failed: ${
          error instanceof Error ? error.message : String(error)
        }`,
      );
    }
    process.exit(0);
  };

  process.once("SIGINT", () => void shutdown("SIGINT"));
  process.once("SIGTERM", () => void shutdown("SIGTERM"));

  try {
    web = await createWebHost({
      runtime,
      workspace,
      host: HOST,
      port,
      stateDir: stateDirectory,
      trustedLan: true,
      restrictWorkspace: true,
    });
    web.server.on("request", (request, response) => {
      void web
        .handle(request, response, () => {
          if (response.headersSent) return;
          response.writeHead(404, {
            "Content-Type": "text/plain; charset=utf-8",
          });
          response.end("native-core-fixture: API only\n");
        })
        .catch(() => {
          if (response.headersSent) response.destroy();
          else {
            response.writeHead(500, {
              "Content-Type": "text/plain; charset=utf-8",
            });
            response.end("native-core-fixture: internal error\n");
          }
        });
    });

    await new Promise((done, reject) => {
      const onError = (error) => {
        web.server.off("listening", onListening);
        reject(error);
      };
      const onListening = () => {
        web.server.off("error", onError);
        done();
      };
      web.server.once("error", onError);
      web.server.once("listening", onListening);
      web.server.listen(port, HOST);
    });

    const relativeState = relative(ANDROID_ROOT, runRoot);
    console.log("[native-core-fixture] ready");
    console.log(`  origin: ${web.origin}`);
    console.log("  mode: trustedLan API-only (no pairing, no auth)");
    console.log(`  model: ${MODEL} (offline fake; no provider calls)`);
    console.log(`  state: ${relativeState} (removed on stop)`);
    console.log(
      `  android: adb reverse tcp:${port} tcp:${port} && use http://${HOST}:${port}/`,
    );
    console.log(
      "  prompts: hello | workbench | approval | slow | any 中文 text -> stream",
    );
    console.log(
      "  files: README.md, src/example.kt, docs/guide.md (isolated workspace)",
    );
    console.log(
      "  queue: real Core durable input-queue under state/input-queue (isolated FORGE_HOME)",
    );
    console.log(
      "  data: simulated usage, settings/provider sources, MCP metadata and one sample checkpoint",
    );
    console.log("  stop: Ctrl+C");
  } catch (error) {
    console.error(
      `[native-core-fixture] failed to start: ${
        error instanceof Error ? error.message : String(error)
      }`,
    );
    await cleanup().catch(() => undefined);
    process.exitCode = 1;
  }
}

await main();
